Sure! Here's a simple JavaScript function that switches the order of adjectives in a sentence:

```javascript
function swapAdjectives(sentence) {
  // Split the sentence into an array of words
  let words = sentence.split(' ');

  // Find the index of the second adjective (the one between the noun and the verb)
  let secondAdjIndex = -1;
  for (let I = 0; I < words.length; i++) {
    const isFirstAdj = words[i].endsWith('ly') && !words[i - 1].endsWith('ly');
    const isSecondAdj = words[i].endsWith('ly') && words[i - 1].endsWith('ly');
    if (isFirstAdj || isSecondAdj) {
      if (isSecondAdj) {
        secondAdjIndex = i;
      }
      continue;
    }
  }

  // If we couldn't find both adjectives, return the original sentence
  if (secondAdjIndex === -1) {
    return sentence;
  }

  // Swap the positions of the first and second adjectives
  [words[secondAdjIndex], words[secondAdjIndex - 1]] = [words[secondAdjIndex - 1], words[secondAdjIndex]];

  // Join the words back into a sentence
  return words.join(' ');
}

// Example usage:
const originalSentence = "Beautiful green trees are in the park";
const reorderedSentence = swapAdjectives(originalSentence);
console.log(reorderedSentence); // Output: "Green beautiful trees are in the park"
```

This function uses regular expressions to check whether a word ends with `ly`, which is a common indicator of an adjective in English. It then searches for both the first and second adjectives in the sentence, and swaps their positions before joining the words back into a sentence.

