Here's an implementation in MATLAB that converts a given phrase to its Morse Code representation using the provided table:

```matlab
% Define the Morse Code dictionary
morseCode = {'. ', '-... ', '-.-.', '-.. ', '. ', '..- ', '--.', '.... ', '.. ', '.--- ', '-.', '.-.. ', '--', '-.', '---', '.--.', '--.- ', '.-.', '... ', '- ', '..- ', '...- ', '.--', '-..- ', '-.--', '--..'};

% Convert the input phrase to uppercase and split into characters
inputPhrase = input('Enter your message: ');
inputChars = inputPhrase(inputPhrase ~= ' ').';

% Initialize the output signal with silence (space between words)
outputSignal = [];

% Loop through each character and convert to Morse Code
for ii = 1:length(inputChars)
    % Get the corresponding Morse Code signal
    morseSignal = morseCode{inputChars(ii)};

    % Append to the output signal
    outputSignal = [outputSignal; morseSignal];

    % Add a space (silence) between words
    if ii == length(inputChars) || inputChars(ii+1) ~= ' '
        outputSignal = [outputSignal; ''];
    end
end

% Play the output signal at 1000 baud rate (Morse Code speed)
fskmodem('tx', 'sine', 'SampleRate', 1000, 'Frequency', 0, 'DataRate', 1000, 'Data', outputSignal);
```

